function gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){var t=b;b=a%b;a=t;}return a;}
function modinv(a,m){a=((a%m)+m)%m;for(var x=1;x<m;x++)if((a*x)%m===1)return x;return null;}
function affineEnc(text,a,b){if(gcd(a,26)!==1)throw new Error('a 必须与 26 互质');var out='';for(var i=0;i<text.length;i++){var c=text.charCodeAt(i);if(c>=65&&c<=90){out+=String.fromCharCode((a*(c-65)+b)%26+65);}else if(c>=97&&c<=122){out+=String.fromCharCode((a*(c-97)+b)%26+97);}else out+=text[i];}return out;}
function affineDec(text,a,b){if(gcd(a,26)!==1)throw new Error('a 必须与 26 互质');var inv=modinv(a,26);if(inv==null)throw new Error('a 无模逆');var out='';for(var i=0;i<text.length;i++){var c=text.charCodeAt(i);if(c>=65&&c<=90){out+=String.fromCharCode(((inv*((c-65)-b))%26+26)%26+65);}else if(c>=97&&c<=122){out+=String.fromCharCode(((inv*((c-97)-b))%26+26)%26+97);}else out+=text[i];}return out;}
var EXPORTS = { affineEnc:affineEnc, affineDec:affineDec, gcd:gcd, modinv:modinv };


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AffineForgePure = EXPORTS; }
